// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address sender, address target, bool emergency) public {
        // Use the deployer as the DAO to allow flashEnabled modifier
        vm.assume(sender != address(0) && target != address(0));

        // First, configure flash governance to use a mock ERC20 that will approve
        // We need to make transferFrom succeed for the assertGovernanceApproved call
        // Deploy a simple ERC20 that always returns true for transferFrom
        vm.assume(sender != address(c)); // avoid self-revert

        // Set up the DAO to accept this sender as a successful proposal
        // This is a simplification: we need the assertGovernanceApproved to not revert
        // on the flashEnabled check, so we make sender the DAO

        // Actually, the simplest is to make the test contract the DAO (already true)
        // and then call directly as the DAO

        // We need the transferFrom to succeed, so we need an asset that returns true
        // Deploy a mock in the test
        address asset = address(new MockERC20());

        // Configure flash governance with this asset
        c.configureFlashGovernance(asset, 1e18, 1 days, false);

        // Mock the token to transfer the required amount
        MockERC20(asset).mint(sender, 1e18);
        vm.prank(sender);
        MockERC20(asset).approve(address(c), 1e18);

        // Call assertGovernanceApproved as the DAO (this contract)
        vm.prank(sender);
        // It may revert due to various conditions; we just call it
        // The property is about the state after the call
        // If it reverts, configured is still true in reference; false in mutant
        // We need to catch revert and check configured

        (bool success, ) = address(c).call(abi.encodeWithSelector(c.assertGovernanceApproved.selector, sender, target, emergency));

        // The general rule: configured should always be true
        assertTrue(c.configured() == true);
    }
}

contract MockERC20 {
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    function mint(address to, uint256 amount) external {
        balanceOf[to] += amount;
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        require(balanceOf[from] >= amount && allowance[from][msg.sender] >= amount);
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        allowance[from][msg.sender] -= amount;
        return true;
    }
}

