pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address sender, address target, bool emergency) public {
        vm.assume(sender != address(0) && target != address(0));
        // Ensure the contract is configured
        if (!c.configured()) {
            c.endConfiguration();
        }
        // Ensure flashGovernanceConfig.asset is set to a mock ERC20 that always returns true for transferFrom
        // For simplicity, we assume the asset is already set; otherwise, we skip
        if (c.flashGovernanceConfig().asset == address(0)) {
            return;
        }
        // Use vm.prank to simulate the sender
        vm.prank(sender);
        (bool success, ) = address(c).call(
            abi.encodeWithSelector(c.assertGovernanceApproved.selector, sender, target, emergency)
        );
        if (success) {
            assertTrue(c.configured(), "configured should be true after successful assertGovernanceApproved");
        }
    }
}

