pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(
        address sender,
        address target,
        address asset,
        uint256 amount,
        uint256 unlockTime,
        bool assetBurnable
    ) public {
        // Bound inputs to reasonable values
        amount = bound(amount, 1, 1e30);
        unlockTime = bound(unlockTime, 1, 365 days);

        // Assume sender has enough tokens
        vm.assume(asset != address(0));

        // Set up the flash governance config
        vm.prank(address(this)); // DAO can make proposals
        c.configureFlashGovernance(asset, amount, unlockTime, assetBurnable);

        // Give sender tokens and approve
        deal(asset, sender, amount);
        vm.prank(sender);
        IERC20(asset).approve(address(c), amount);

        // Set the governance contract
        vm.prank(address(this));
        c.setDAO(address(this));

        // Ensure the pending unlock time is less than block.timestamp
        vm.warp(block.timestamp + unlockTime + 1);

        // Now call assertGovernanceApproved - should succeed if transferFrom works
        vm.prank(sender);
        try c.assertGovernanceApproved(sender, target, false) {
            // Success case: configured must still be true
            assertTrue(c.configured(), "configured should be true after successful call");
        } catch {
            // Revert is also ok, but configured must still be true
        }
    }
}

interface IERC20 {
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
}

