// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address dao, address caller) public {
        vm.assume(caller != address(0));

        // Capture initial DAO
        address initialDao = c.DAO();

        // Call setDAO from caller (it may revert due to the require)
        // We need to handle the case where the call reverts differently
        (bool success, ) = address(c).call(abi.encodeWithSignature("setDAO(address)", dao));

        // The bug mutates setDAO to also reset DAO to address(0) before the require
        // So even if the call reverts, DAO may have been changed to address(0) by the bug
        // while in the reference it would remain unchanged if caller != initialDao and configured
        address finalDao = c.DAO();

        // The rule: finalDao must equal dao if the call succeeded, 
        // or equal initialDao if the call reverted (DAO unchanged)
        // But the bug makes DAO = address(0) before checking the require
        // So if the call reverts, buggy version will have DAO = address(0)
        // while reference keeps DAO = initialDao
        if (success) {
            assertTrue(finalDao == dao, "setDAO should set DAO to the argument");
        } else {
            assertTrue(finalDao == initialDao, "setDAO should not change DAO on revert");
        }
    }
}

